<?php
namespace App\Models;
use App\Enums\AgreementStatus;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['agreement_code','customer_id','customer_requirement_id','assignment_id','worker_id','service_id','duty_type_id','agreement_date','start_date','end_date','tenure_text','monthly_salary','monthly_agency_service_charge','working_hours_text','monthly_leave_text','work_location','gender_preference','house_type','status','terms_snapshot','customer_name_snapshot','customer_address_snapshot','customer_mobile_snapshot','customer_email_snapshot','worker_name_snapshot','worker_code_snapshot','agency_name_snapshot','agency_address_snapshot','agency_phone_snapshot','agency_email_snapshot','agency_gst_snapshot','agency_logo_path','customer_signature_path','customer_signed_at','authorized_person_name','agency_signature_path','agency_stamp_path','agency_signed_at','pdf_path','pdf_version','pdf_generated_at','created_by','updated_by'])]
class Agreement extends Model {protected static function booted():void{static::updating(fn(self $m)=>$m->isDirty('agreement_code')?$m->agreement_code=$m->getOriginal('agreement_code'):null);}public function customer():BelongsTo{return $this->belongsTo(Customer::class);}public function requirement():BelongsTo{return $this->belongsTo(CustomerRequirement::class,'customer_requirement_id');}public function assignment():BelongsTo{return $this->belongsTo(Assignment::class);}public function worker():BelongsTo{return $this->belongsTo(Worker::class);}public function service():BelongsTo{return $this->belongsTo(Service::class);}public function dutyType():BelongsTo{return $this->belongsTo(DutyType::class);}public function statusHistory():HasMany{return $this->hasMany(AgreementStatusHistory::class);}public function versions():HasMany{return $this->hasMany(AgreementVersion::class);}public function invoices():HasMany{return $this->hasMany(Invoice::class);}protected function casts():array{return ['agreement_date'=>'date','start_date'=>'date','end_date'=>'date','customer_signed_at'=>'datetime','agency_signed_at'=>'datetime','pdf_generated_at'=>'datetime','monthly_salary'=>'decimal:2','monthly_agency_service_charge'=>'decimal:2','status'=>AgreementStatus::class];}}
